  'stuSess.refundContactNote': 'Palautusta varten ota yhteyttä <a href="mailto:info@tutlio.lt" class="text-amber-800 underline">info@tutlio.lt</a>.',
  'stuSess.refundSuccessStripeNote': '<p class="text-emerald-900 text-sm mb-2">Kysymyksiä tai ongelmia? Ota yhteyttä <a href="mailto:info@tutlio.lt" class="underline font-medium">info@tutlio.lt</a>.</p><p class="font-semibold text-emerald-900">Palautuksesi on aloitettu Stripen kautta.</p><p class="text-emerald-800 mt-1">Korttipalautukset saapuvat yleensä noin <strong>5–10 arkipäivässä</strong> (pankit voivat vaihdella). Jos et saa palautusta normaalissa aikataulussa, lähetä sähköpostia osoitteeseen <a href="mailto:info@tutlio.lt" class="text-emerald-900 underline font-medium">info@tutlio.lt</a>.</p>',
  'stuSess.refundSuccessManualTutor': '<p>Tätä tuntia ei näytä maksetun Tutlio Stripen kautta (esim. tilisiirto tai käteinen). Automaattista palautusta ei ole.</p><p class="mt-2">Palautuksen järjestämiseksi ota yhteyttä tutoriisi <strong>{tutor}</strong> — käytä sähköpostia tai tietoja varauksistasi tai suoraan tutorilta.</p>',
  'stuSess.refundSuccessManualOrg': '<p>Tätä tuntia ei näytä maksetun Tutlio Stripen kautta (esim. tilisiirto tai käteinen). Automaattista palautusta ei ole.</p><p class="mt-2">Koska opiskelet organisaation kautta, ota yhteyttä <strong>organisaation ylläpitäjään</strong> (tutorisi kautta tai organisaation julkaistuista yhteystiedoista).</p>',
