  'feature.cancellation.pageTitle': 'Peruutussäännöt ja myöhäisen peruutuksen maksut opettajille',
  'feature.cancellation.pageDesc': 'Aseta selkeät peruutusajat ja automaattiset myöhäisen peruutuksen maksut. Kun oppilaat peruvat, vapautuneet ajat siirtyvät suoraan jonotuslistallesi.',
  'feature.cancellation.detailsTitle': 'Näin peruutussäännöt toimivat',
  'feature.cancellation.deadlines': 'Peruutusajat',
  'feature.cancellation.deadlinesDesc': 'Määritä, kuinka aikaisin oppilaiden on peruttava (esim. 24 tuntia ennen tuntia) välttääkseen peruutusmaksun.',
  'feature.cancellation.fees': 'Automaattiset myöhäisen peruutuksen maksut',
  'feature.cancellation.feesDesc': 'Aseta prosenttimaksu (esim. 50 % tunnin hinnasta), joka veloitetaan automaattisesti, kun oppilas peruu liian myöhään.',
  'feature.cancellation.transparency': 'Selkeä viestintä oppilaiden kanssa',
  'feature.cancellation.transparencyDesc': 'Oppilaat näkevät peruutuskäytäntösi heti varatessaan. Ei yllätyksiä — vain ammattimaiset, reilut säännöt.',
  'feature.cancellation.waitlistLink': 'Jonotuslistan integrointi',
  'feature.cancellation.waitlistLinkDesc': 'Peruutetut ajat tarjotaan heti jonotuslistalla oleville oppilaille, joten aikataulusi pysyy täynnä ja tulosi turvattuina.',
  'feature.cancellation.faq.howSetQ': 'Miten asetan peruutussäännöt?',
  'feature.cancellation.faq.howSetA': 'Siirry tuntiasetuksiisi ja määritä peruutusaika (tunteja ennen tuntia) ja myöhäisen peruutuksen maksuprosentti. Järjestelmä soveltaa niitä automaattisesti.',
  'feature.cancellation.faq.refundQ': 'Mitä peruutusmaksulle tapahtuu?',
